"""Audit frozen accelerated history,paired fast14 timing and complete quality."""
import argparse,json,hashlib,statistics,math,sys,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.report_quality_speed_final import FIELDS,fmt,table
from scripts.search_quality_speed import save

def read(p):return json.loads(p.read_text())
def csvwrite(p,rows):
 with p.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=a.output;plan=read(r/'quality/plan.json');done=read(r/'quality/completion.json');selection=read(r/'selection.json');assert done['complete'] and len(done['runs'])==18 and all(v['fast14_timing_complete'] for v in done['runs'])
 for path,sha in plan['source_sha256'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha,path
 c=selection['candidates'][0];cfg=read(ROOT/c['config']);assert hashlib.sha256((ROOT/c['config']).read_bytes()).hexdigest()==c['config_sha256'];old=read(ROOT/'outputs/history_teacher_20261106/summary.json');fast=read(ROOT/'outputs/quality_speed_search_20261106/current_probe_summary.json');rows=[];layers=[];macros=[];audit=[]
 for ds,scenes in plan['datasets'].items():
  for scene in scenes:
   folder=r/'quality/runs'/c['name']/ds/scene;x=read(folder/'result.json');control=read(r/'quality/fast14_timing'/ds/scene/'timing_result.json');reference=read(ROOT/'outputs/quality_speed_search_20261106/current_probe_quality/runs/cp4_c10_prior_residual_middle18'/ds/scene/'result.json');previous=read(ROOT/'outputs/history_teacher_20261106/quality/runs/teacher_history_block64_anchor8'/ds/scene/'result.json');assert x['quality']['complete'] and not control['quality']['complete'] and all(v is None for v in control['quality']['values'].values());assert x['input']==control['input']==reference['input']==previous['input'];assert x['quality_protocol']==reference['quality_protocol']==previous['quality_protocol'];assert all(x['config'][k]==v for k,v in cfg.items())
   assert control['config']==reference['config'] or all(control['config'][k]==v for k,v in reference['config'].items())
   for k in ['cluster_fraction','layer_retentions','query_group_size','teacher_history_probes','teacher_history_samples','teacher_history_anchor_gain','teacher_history_update_gain','streamed_history_prior_weight','rep_history_execution','rep_history_loss','shared_value_features','dual_iterations','dense_special_queries']:assert x['config'][k]==previous['config'][k],k
   m=read(r/'quality/monitors'/f"{c['name']}_{ds}_{scene}.json");cm=read(r/'quality/monitors'/f'fast14_{ds}_{scene}.json');assert m['gpu_uuid']==cm['gpu_uuid'] and all(v['returncode']==0 and not v['same_gpu_overlap_detected'] and v['max_simultaneous_gpu_applications']==1 for v in [m,cm])
   for v in [x,control]:assert v['timing']['warmup']==1 and v['timing']['repeats']==3 and v['timing']['median_seconds']==statistics.median(s['seconds'] for s in v['timing']['samples'])
   q=x['quality']['values'];assert all(math.isfinite(q[k]) for k in FIELDS) and abs(q['cd']-(q['acc']+q['comp'])/2)<1e-9;lr=read(folder/'layers.json');assert len(lr)==24
   for layer in lr:
    assert layer['actual_unique_density']<.25 and layer['selected_edge_recompute_qk_per_head']==0 and layer['history_probabilities_used']==(layer['layer']>0)
    layers.append(dict(dataset=ds,scene=scene,layer=layer['layer'],actual_unique_density=layer['actual_unique_density'],actual_sparsity=1-layer['actual_unique_density'],fine_clusters=layer['fine_clusters'],patch_budget=layer['patch_budget'],history_cache_bytes=layer['history_probability_cache_bytes'],history_evidence_scratch_bytes=layer['history_evidence_scratch_peak_bytes'],selected_edge_recomputed_qk=0))
   seconds=x['timing']['median_seconds'];fc=control['timing']['median_seconds'];row=dict(dataset=ds,scene=scene,frames=x['frames'],**q,seconds=seconds,paired_fast14_seconds=fc,speedup_vs_fast14=fc/seconds,not_slower_than_fast14=seconds<=fc,warm_peak_allocated_gib=max(v['peak_allocated_gib'] for v in x['timing']['samples']),warm_peak_reserved_gib=max(v['peak_reserved_gib'] for v in x['timing']['samples']),including_cold_peak_gib=max(v['peak_allocated_gib'] for v in x['timing']['samples']+x['timing']['cold_samples']),actual_unique_density=statistics.mean(v['actual_unique_density'] for v in lr),history_cache_mib=max(v['history_probability_cache_bytes'] for v in lr)/2**20,evidence_scratch_mib=max(v['history_evidence_scratch_peak_bytes'] for v in lr)/2**20,speedup_vs_dense=None,speedup_reason='Dense not rerun;no paired Dense timing authorized');rows.append(row);save(folder/'reporting.json',row);audit.append(dict(dataset=ds,scene=scene,same_gpu=True,no_overlap=True,input_checkpoint_protocol_matched=True,source_and_config_frozen=True,fast14_quality_reused=True))
  rr=[v for v in rows if v['dataset']==ds];m=dict(dataset=ds,scenes=len(rr),**{k:statistics.mean(v[k] for v in rr) for k in FIELDS},seconds=statistics.mean(v['seconds'] for v in rr),paired_fast14_seconds=statistics.mean(v['paired_fast14_seconds'] for v in rr),warm_peak_allocated_gib=max(v['warm_peak_allocated_gib'] for v in rr),warm_peak_reserved_gib=max(v['warm_peak_reserved_gib'] for v in rr),including_cold_peak_gib=max(v['including_cold_peak_gib'] for v in rr),actual_unique_density=statistics.mean(v['actual_unique_density'] for v in rr),history_cache_mib=max(v['history_cache_mib'] for v in rr),evidence_scratch_mib=max(v['evidence_scratch_mib'] for v in rr),scenes_not_slower=sum(v['not_slower_than_fast14'] for v in rr),speedup_vs_dense=None)
  m['speedup_vs_fast14']=m['paired_fast14_seconds']/m['seconds'];m['not_slower_than_fast14_macro']=m['speedup_vs_fast14']>=1.;ref=next(v for v in old['macro'] if v['dataset']==ds);m['quality_changes_percent_vs_previous']={k:100*(m[k]/ref[k]-1) for k in FIELDS};m['recon_within2pct_vs_previous']=all(m[k]>=.98*ref[k] if k=='f1' else m[k]<=1.02*ref[k] for k in ['acc','comp','cd','f1']);macros.append(m)
 profile=read(r/'profile/result.json');assert abs(sum(v['seconds'] for v in profile['stages'])-profile['full_gpu_event_seconds'])<1e-4;validation=read(r/'final_rgb128.json');assert validation['config']==cfg
 probability=dict(previous_relative_l1=statistics.mean(v['all_patch_prediction']['relative_l1'] for v in read(ROOT/'outputs/history_teacher_20261106/final_rgb128.json')['probability_transfer']),new_relative_l1=statistics.mean(v['all_patch_prediction']['relative_l1'] for v in validation['probability_transfer']))
 result=dict(complete=True,macro=macros,previous_history_reference=old['macro'],historical_fast14_quality=fast['macro'],paired_fast14_timing_only=True,geometry_control_reruns=False,all_macros_not_slower=all(v['not_slower_than_fast14_macro'] for v in macros),all_scenes_not_slower=all(v['not_slower_than_fast14'] for v in rows),probability_validation=probability,speedup_vs_dense=None,dense_reason='No paired Dense timing authorized');save(r/'summary.json',result);save(r/'audit.json',dict(passed=True,rows=audit));csvwrite(r/'macro.csv',[{k:v for k,v in m.items() if not isinstance(v,dict)} for m in macros]);csvwrite(r/'per_scene.csv',rows);csvwrite(r/'per_layer.csv',layers)
 compare=[]
 for ds in plan['datasets']:
  for label,rr in [('优化前历史版（已有）',old['macro']),('fast14（质量复用）',fast['macro']),('优化后历史版（本轮）',macros)]:compare += [dict(v,label=label) for v in rr if v['dataset']==ds]
 mask_names={'current_value_geometry','history_key_preparation','current_coarse_observation','history_probability_prediction','current_prior_state_selection','bootstrap_full_key_probability'};mask=sum(v['seconds'] for v in profile['stages'] if v['operation'] in mask_names)
 lines=['# 历史证据与Mask构建的GPU工程优化','','7Scenes全七场景各128帧；ETH3D十一场景14–76帧，沿用精确输入帧表、checkpoint、预处理、位姿与点云协议。只重跑修改后的方法质量；fast14仅按明确许可补逐场景同GPU计时，质量复用。Dense/SAF3R未重跑。AUC/F1为%，距离为m，CD=(ACC+Comp)/2未平方。','', '## 速度验收','',table(['数据集','新版完整前向 s','fast14配对 s','相对fast14速度','宏平均不慢于fast14','不慢于fast14的场景数','热显存峰值 GiB'],[[v['dataset'],f"{v['seconds']:.6f}",f"{v['paired_fast14_seconds']:.6f}",f"{v['speedup_vs_fast14']:.4f}x",v['not_slower_than_fast14_macro'],f"{v['scenes_not_slower']}/{v['scenes']}",f"{v['warm_peak_allocated_gib']:.3f}"] for v in macros]),'', '每场景同一卡顺序执行新版和fast14，均1次预热+3次完整前向取中位数。数据集时间为等场景平均，速度比=各场景fast14中位耗时之和/各场景新版中位耗时之和。初始化、聚类、观测、状态选择、历史保存、特殊Query和预测头全部计入。加载与CPU几何评分不计入模型前向。逐场景超过fast14的情况不隐藏；宏平均通过不等于每种输入都通过。Dense配对速度比N/A，未获许可重跑Dense，Dense定义1.00x。','', '## 稀疏率','','保留率L0–5为10%、L6–17为18%、L18–23为10%；名义平均14%，即稀疏率86%。保持10%簇、4探针、每64-Key块8个采样、历史权重0.75、原状态损失、16轮预算、256 Query共享Mask及特殊Query修正。提高处理窗口64→128只合批独立Query组，不改变共享Mask的Query组大小。','',table(['数据集','实际唯一边保留率 %','实际稀疏率 %'],[[v['dataset'],f"{v['actual_unique_density']*100:.5f}",f"{(1-v['actual_unique_density'])*100:.5f}"] for v in macros]),'', '实际值计入特殊Query对所有Key的完整Attention。没有通过降低Key保留预算实现本轮速度收益。','', '## 核心优化','','1. 直接导出正式AV使用的BF16概率tile，保留tile偏移和未补偿选中分母。通过逆补偿恢复每条历史边的条件概率；不再编码相对logit，不再在缓存更新时逐边做指数。数学概率公式不变，机器量化由FP16相对logit改为AV原生BF16概率，有舍入差异。','2. 保持MMA布局，只由探针行写出，移除主路径跨Warp gather。延后V加载和去补偿分母归约，减少同时存活的矩阵和寄存器溢出；通过无GT微基准选择2stage。','3. 合并当前Key池化、锚点收集与固定Head-sketch投影，避免完整FP32 Key中间张量。VGGT16头的投影系数±0.125可精确表示为BF16，输出投影只有浮点加法顺序的小差异（单测≤1e-6）。Value聚类特征保持原实现。','4. 整层一次粗观测，按窗口使用视图；直接保留head-mean观测为下一层缓存，去掉窗口间重复调度和复制。窗口128与64的算法相同。','', '仍使用上一层细粒度概率和当前粗观测，只有L0一次全Key初始化；没有切换成每层全Key概率。每层聚类、概率、状态均更新，没有冻结跨层Mask。','', '## 概率数值验证','',table(['独立TUM128','相对fast4概率的L1'],[['优化前',f"{probability['previous_relative_l1']:.6f}"],['优化后',f"{probability['new_relative_l1']:.6f}"]]),'', '25项数值/结构测试覆盖正式AV、强补偿、尾Query与重复探针、历史条件概率、后验更新、质量归一化及融合Key准备。数学等价不意味着位级相同，完整几何评测另列。未根据目标测试GT选择Kernel或参数；正式质量评测前冻结实现和配置，未从多次完整质量中挑最佳。','', '## 六项质量','',table(['数据集','方法','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %'],[[v['dataset'],v['label'],*[fmt(k,v[k]) for k in FIELDS]] for v in compare]),'',table(['数据集',*[k+'相对优化前变化 %' for k in FIELDS],'重建退化≤2%'],[[v['dataset'],*[f"{v['quality_changes_percent_vs_previous'][k]:+.3f}" for k in FIELDS],v['recon_within2pct_vs_previous']] for v in macros]),'', '## 不重复计时的Profile','',table(['阶段','秒','完整前向占比 %'],[[v['operation'],f"{v['seconds']:.6f}",f"{v['percent']:.3f}"] for v in profile['stages']]),'', f"明确归类的Mask构建阶段合计{mask:.6f}s；未归类的global准备/收尾另列，含实际Key映射和输出投影等，不能全部归因Mask。Attention行包含内联证据导出和选中分母；teacher_cache_update仅是后续head-mean归约与缓存写回，二者不重复。无法把这次profile的AV和另一批裸AV直接相减认定真实导出成本。",'', '源Profile与旧历史版Profile是不同批次，供瓶颈参考，不冒充配对速度。独立微基准比较了原生AV与带证据AV，均包含各自函数内全部初始化/导出工作。被排除的更大分块、寄存器限制、FP32原始logit、拆分探针和布局试验均保留日志；它们是诊断，六项质量N/A，不是额外完整质量控制跑。','', '## 逐场景质量和配对速度','',table(['数据集','场景','帧','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %','新版 s','fast14 s','相对fast14'],[[v['dataset'],v['scene'],v['frames'],*[fmt(k,v[k]) for k in FIELDS],f"{v['seconds']:.5f}",f"{v['paired_fast14_seconds']:.5f}",f"{v['speedup_vs_fast14']:.4f}x"] for v in rows]),'', '重建阈值/下采样：7Scenes0.05/0.0078125m，ETH3D0.25/0.0390625m。checkpoint SHA b08a43baa2db1aad9718e71e098831b8ad32f6f6826c802e9eb714aa34420969。原始JSON、CSV、代码/配置SHA、源码快照、GPU独占监控与冷/热allocated/reserved显存均保留。']
 lines+=['','## 采用结论','','本14%保留率工程版未通过全部约束：7Scenes宏平均比fast14略快，ETH3D宏平均仍略慢；两套数据均有重建指标退化超过2%。因此保留独立实验配置，不能宣称性能保持不变或全部输入均已快于fast14。后续90%稀疏实验单独冻结和评测，不按这里的目标测试分数选择其预算。']
 (r/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
